/bin/zsh -lc "python3 - <<'PY'
from pathlib import Path
p=[]
for line in Path('prog.pw9').read_text().splitlines():
    line=line.split(';',1)[0].strip()
    if line: p.append(line.split())
r={x:0 for x in 'abcd'}
ip=0
steps=0
outs=[]
while 0<=ip<len(p):
    ins=p[ip]; op=ins[0]; steps+=1; nxt=ip+1
    def val(x): return r[x] if x in r else int(x)
    if op=='set': r[ins[1]]=val(ins[2])%65536
    elif op=='add': r[ins[1]]=(r[ins[1]]+val(ins[2]))%65536
    elif op=='mul': r[ins[1]]=(r[ins[1]]*val(ins[2]))%65536
    elif op=='mod':
        x=val(ins[2]); r[ins[1]]=r[ins[1]]%x if x>0 else r[ins[1]]
    elif op=='dec': r[ins[1]]=max(0,r[ins[1]]-1)
    elif op=='jnz':
        if val(ins[1])"'!=0: nxt=ip+val(ins[2])
    elif op=='"'skp':
        if val(ins[1])<val(ins[2]): nxt=ip+2
    elif op=='out': outs.append(val(ins[1]))
    ip=nxt
print('n',len(p),'steps',steps,'outs',len(outs),'sum',sum(outs),'regs',r)
print(outs[:5],outs[-5:])
PY"

